    if (field.type === "integer") assert(typeof captured.value === "number" && Number.isSafeInteger(captured.value) && captured.value >= (field.min ?? 0) && captured.value <= (field.max ?? Number.MAX_SAFE_INTEGER), "CASE_SOURCE_VALUE_INVALID", 409);
    if (field.type === "decimal") assert(typeof captured.value === "number" && Number.isFinite(captured.value) && captured.value >= (field.min ?? 0) && captured.value <= (field.max ?? Number.MAX_VALUE), "CASE_SOURCE_VALUE_INVALID", 409);
