  if (row.target_type === "EVENT" && (!row.base_result_id||["CASE06","CASE07"].includes(row.case_id))) {const event = await eventBinding(tx, scope, row.target_id, asOf); assert(event && hashRuleValue(event.target) === hashRuleValue(target), "CASE_NATIVE_TARGET_CHANGED", 412);}
  if(base&&["CASE06","CASE07"].includes(row.case_id)){const program=await nativeEventProgram(tx,scope,base.payload.target,asOf);assert(program.eventIds.includes(target.targetId),"CASE_EVENT_PROGRAM_TARGET_MISMATCH",412);}
