export async function purgeOperationalCaseContexts(tx: Tx, scope: Scope, actorHash?: string) {
  await acquireRuleScopeLocks(tx, ruleScopeLockSet(scope));const plugins=operationalContextPlugins();
  if (actorHash) {
    // The aggregate readers cannot prove independence from this subject. Erase
    // their copied values and native references before the original rows are
    // purged. Role-only metadata and unrelated shared staff checklists survive.
    for(const plugin of plugins)await plugin.purgeActor?.(tx,scope,actorHash);
    const rows=(await sql<ContextRow>`SELECT *,to_char(window_start AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') AS exact_window_start,to_char(window_end AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') AS exact_window_end FROM rule_operational_contexts WHERE ${tenant(scope)} FOR UPDATE`.execute(tx)).rows;
    for(const row of rows){const removed=(row.source_configs??[]).filter(source=>source.sourceId!=="ROLE_ACCESS_NATIVE");if(!removed.length)continue;const ids=removed.map(source=>source.sourceId),sources=(row.source_configs??[]).filter(source=>!ids.includes(source.sourceId));await sql`DELETE FROM rule_operational_fields WHERE ${tenant(scope)} AND context_id=${row.id}::uuid AND source_metadata->>'pluginId' IN (${sql.join(ids)})`.execute(tx);const values=await storedFields(tx,scope,row.id),version=row.version+1,target=targetOf(row);if(logicalTargets.has(target.targetType)&&target.targetType!=="PERMISSION")target.liveVersion=String(version);const contentHash=operationalContextHash(row.case_id,target,version,values,row.base_result_id,contextWindow(row),sources);await sql`UPDATE rule_operational_contexts SET version=${version},live_version=${target.liveVersion},source_configs=${json(sources)},content_hash=${contentHash} WHERE ${tenant(scope)} AND id=${row.id}::uuid`.execute(tx);await cancelAffectedCaseJobs(tx,scope,row.case_id,row.id);}
    await sql`DELETE FROM rule_operational_requests WHERE ${tenant(scope)} AND actor_hash=${actorHash}`.execute(tx);return;
  }
  for(const plugin of plugins)await plugin.purge?.(tx,scope);
  await sql`DELETE FROM rule_operational_contexts WHERE ${tenant(scope)}`.execute(tx);await sql`DELETE FROM rule_operational_case_profiles WHERE ${tenant(scope)}`.execute(tx);await sql`DELETE FROM rule_operational_requests WHERE ${tenant(scope)}`.execute(tx);
}
export async function expireOperationalCaseContexts(tx: Tx, scope: Scope, now: Date) {await acquireRuleScopeLocks(tx, ruleScopeLockSet(scope));for(const plugin of operationalContextPlugins())await plugin.expire?.(tx,scope,now);await sql`DELETE FROM rule_operational_contexts WHERE ${tenant(scope)} AND expires_at<=${now}`.execute(tx); await sql`DELETE FROM rule_operational_case_profiles WHERE ${tenant(scope)} AND expires_at<=${now}`.execute(tx); await sql`DELETE FROM rule_operational_requests WHERE ${tenant(scope)} AND expires_at<=${now}`.execute(tx);}
